import { declareRpcContract, type EdgeMethodTable, type RpcMethod } from "@sand/dune/rpc";

/** Everything the trusted box-desktop webview's preload exchanges with Electron main. */
export interface BoxVncRpcContract {
	readonly methods: {
		readonly readClipboard: RpcMethod<Record<string, never>, string>;
		readonly writeClipboard: RpcMethod<{ readonly text: string }, void>;
		readonly reportUserPresence: RpcMethod<{ readonly isPresent: boolean }, void>;
	};
	readonly events: Record<string, never>;
	readonly capabilities: never;
	readonly failureCodes: never;
}

export const boxVncRpcContract = declareRpcContract<BoxVncRpcContract>("box-vnc");

export const BOX_VNC_METHOD_TABLE: EdgeMethodTable<BoxVncRpcContract> = {
	readClipboard: { args: "none" },
	writeClipboard: { args: "object" },
	reportUserPresence: { args: "object" },
};
