import type { SandVncLivenessPhase, SandVncLivenessReport } from "./observability/telemetry.js";

export const VNC_LIVENESS_CHANNEL = "sand:vnc-liveness";
export const VNC_LIVENESS_WINDOW_MS = 10_000;
export const VNC_LIVENESS_MIN_IMPACTFUL_INPUTS = 3;

const VNC_LIVENESS_PHASES: ReadonlySet<string> = new Set<SandVncLivenessPhase>(["post_connect"]);

function isBoundedCount(value: unknown): value is number {
	return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

export function isValidVncLivenessReport(value: unknown): value is SandVncLivenessReport {
	if (typeof value !== "object" || value === null) return false;
	const report = value as Record<string, unknown>;
	return (
		typeof report.phase === "string" &&
		VNC_LIVENESS_PHASES.has(report.phase) &&
		isBoundedCount(report.stallMs) &&
		isBoundedCount(report.keys) &&
		isBoundedCount(report.clicks) &&
		isBoundedCount(report.moves) &&
		isBoundedCount(report.inBytes)
	);
}
