export function createViewerVisibilityGate(): {
	isVisible(): boolean;
	update(value: unknown): boolean;
} {
	let isVisible = false;
	return {
		isVisible: () => isVisible,
		update(value: unknown): boolean {
			const next = value === true;
			const becameVisible = next && !isVisible;
			isVisible = next;
			return becameVisible;
		},
	};
}
