export interface Disposable {
	dispose(): void;
}

export interface Clock {
	now(): number;
	// Elapsed-time consumers such as connection-health TTLs need a reading
	// NTP cannot rewind or jump: Date.now() regresses under clock steps, so
	// deltas built on it can go negative or spike. monotonicNow() readings
	// only move forward and are comparable against each other only.
	monotonicNow(): number;
	schedule(delayMs: number, fn: () => void): Disposable;
}

export const realClock: Clock = {
	now: () => Date.now(),
	monotonicNow: () => performance.now(),
	schedule(delayMs, fn) {
		assertDelay(delayMs);
		let active = true;
		const timer = globalThis.setTimeout(() => {
			if (!active) return;
			active = false;
			fn();
		}, delayMs);
		// A policy timer must never be the reason a process stays alive. Every
		// policy built on this clock is application bookkeeping — a debounce, a
		// poll, a watchdog, an expiry — and a process that should keep running has
		// a socket or an explicit wait for that. Optional-called because only Node
		// timers carry it; in a browser this is a no-op.
		(timer as { unref?: () => void }).unref?.();

		return {
			dispose() {
				if (!active) return;
				active = false;
				globalThis.clearTimeout(timer);
			},
		};
	},
};

interface ScheduledTask {
	readonly id: number;
	readonly dueAt: number;
	readonly fn: () => void;
}

export class DeterministicClock implements Clock {
	private currentTime = 0;
	private nextId = 0;
	private readonly tasks = new Map<number, ScheduledTask>();

	now(): number {
		return this.currentTime;
	}

	monotonicNow(): number {
		return this.currentTime;
	}

	schedule(delayMs: number, fn: () => void): Disposable {
		assertDelay(delayMs);
		const task: ScheduledTask = {
			id: this.nextId,
			dueAt: this.currentTime + delayMs,
			fn,
		};
		this.nextId += 1;
		this.tasks.set(task.id, task);

		return {
			dispose: () => {
				this.tasks.delete(task.id);
			},
		};
	}

	advance(ms: number): void {
		assertDelay(ms);
		const targetTime = this.currentTime + ms;

		for (;;) {
			const task = this.nextTaskAtOrBefore(targetTime);
			if (task == null) break;
			this.currentTime = task.dueAt;
			this.tasks.delete(task.id);
			task.fn();
		}

		this.currentTime = Math.max(this.currentTime, targetTime);
	}

	flush(): void {
		this.advance(0);
	}

	pendingCount(): number {
		return this.tasks.size;
	}

	private nextTaskAtOrBefore(targetTime: number): ScheduledTask | undefined {
		let next: ScheduledTask | undefined;

		for (const task of this.tasks.values()) {
			if (task.dueAt > targetTime) continue;
			if (
				next == null ||
				task.dueAt < next.dueAt ||
				(task.dueAt === next.dueAt && task.id < next.id)
			) {
				next = task;
			}
		}

		return next;
	}
}

function assertDelay(delayMs: number): void {
	if (!Number.isFinite(delayMs) || delayMs < 0) {
		throw new RangeError("delayMs must be a finite non-negative number");
	}
}
